<?php
declare(strict_types=1);
require_once __DIR__.'/../src/Qipu.php';
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
function n(string $k):int{$v=$_GET[$k]??null;if(!is_string($v)||!preg_match('/\A(?:0|[1-9][0-9]{0,9})\z/',$v))throw new StorageError(400,'Invalid '.$k);return (int)$v;}
function str(string $k):string{$v=$_GET[$k]??null;if(!is_string($v))throw new StorageError(400,'Missing '.$k);return $v;}
function out(int $s,array $v):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo QipuDemo::json($v);exit;}
try{$root=getenv('QIPU_ROOT')?:__DIR__.'/../data-v2';if(!is_dir($root)&&!@mkdir($root,0700,true)&&!is_dir($root))throw new StorageError(503,'Storage unavailable');$q=new QipuDemo($root);$op=str('op');$m=$_SERVER['REQUEST_METHOD'];$result=$q->locked(function()use($q,$op,$m){if($m==='GET'){return match($op){'head'=>$q->cut(str('stream')),'cut'=>$q->cut(str('stream'),n('offset')),'read'=>$q->read(str('stream'),n('offset'),n('length')),'pending'=>$q->pending(),default=>throw new StorageError(405,'Unknown operation')};}if($m==='POST'){return match($op){'submit'=>$q->submit(str('node'),n('index'),n('offset'),file_get_contents('php://input',false,null,0,QipuDemo::MAXBODY+64)?:''),'decide'=>$q->decide(str('node'),n('index'),n('bit')),default=>throw new StorageError(405,'Unknown operation')};}throw new StorageError(405,'Invalid method');});if($op==='read'){header('Content-Type: application/octet-stream');header('X-Confirmed-End: '.$result['end']);header('Content-Length: '.strlen($result['bytes']));echo $result['bytes'];exit;}out(200,$result);}catch(StorageError $e){out($e->status,['error'=>$e->getMessage()]);}catch(JsonException $e){out(422,['error'=>'Invalid JSON']);}catch(Throwable $e){error_log($e->getMessage());out(503,['error'=>'Uncertain state; retry same operation']);}
